I=[]
I.append(R(6321052,"टर्की सॉसेज और ताज़ी तुलसी की झटपट फ़्रिटाटा","फ़्रिटाटा नाश्ते के बेहतरीन विकल्प हैं जिन्हें बड़ी मात्रा में पकाया जा सकता है, ताकि आप कई हिस्से बना सकें और उन्हें पूरे सप्ताह में बाँटकर खा सकें।","4","फ़्रिटाटा की 1/4 फाँक",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","8 औंस कम सोडियम वाले टर्की सॉसेज (छोटे टुकड़ों में कटे हुए)","1 1/2 कप अंडे का विकल्प","3/4 औंस मोज़ेरेला चीज़ (कम वसा वाला, कद्दूकस किया हुआ)","1/2 कप हरी प्याज़ (बारीक कटी हुई)","1 कप टमाटर (छोटे टुकड़ों में कटे हुए)","1/4 कप ताज़ी तुलसी (कटी हुई)"],
["एक बड़ी नॉनस्टिक कड़ाही पर हल्का सा कुकिंग स्प्रे करें। मध्यम आँच पर रखें। सॉसेज डालें और बीच-बीच में चलाते हुए 3 मिनट या भूरा होना शुरू होने तक पकाएँ।","अंडे के विकल्प को सॉसेज पर बराबर डालें और 1 मिनट पकाएँ। चलाएँ नहीं। फिर, कच्चे अंडे को नीचे बहने देने के लिए धीरे से उठाएँ। आँच से हटाएँ और बाकी पकने दें।","ऊपर से चीज़, हरी प्याज़, टमाटर और तुलसी बराबर छिड़कें।"]))
I.append(R(6321815,"ब्लूबेरी स्मूदी बाउल","यह कम वसा वाली, बहुत कम वसा वाली और शाकाहारी रेसिपी है जिसमें ब्लूबेरी शामिल हैं। यह ब्लूबेरी स्मूदी बाउल मलाईदार ग्रीक योगर्ट को फल और थोड़े से मसाले के साथ मिलाकर एक ताज़गी भरा, पोषक तत्वों से भरपूर नाश्ता बनाता है। चिया बीजों से फ़ाइबर, योगर्ट से प्रोटीन और फल से प्राकृतिक मिठास के साथ, यह दिन की शुरुआत करने का एक संतुलित तरीका है। अतिरिक्त चीनी के बिना ऊर्जा का स्तर स्थिर रखने के लिए यह एक बेहतरीन विकल्प है।","2","प्रति हिस्सा 1 कटोरा",
["1 कप जमे हुए ब्लूबेरी","1/2 कप स्किम मिल्क","1 मध्यम केला (पका हुआ)","1 कप सादा ग्रीक योगर्ट","1 छोटा चम्मच शुद्ध वनीला एक्स्ट्रैक्ट","1/2 कप ताज़े ब्लूबेरी","2 छोटा चम्मच कम वसा वाला ग्रेनोला","2 छोटा चम्मच चिया बीज","1 छोटा चम्मच पिसी दालचीनी"],
["ब्लेंडर में जमे हुए ब्लूबेरी, दूध, केला, योगर्ट और वनीला एक्स्ट्रैक्ट को मिलाएँ। चिकना और मलाईदार होने तक ब्लेंड करें।","स्मूदी के मिश्रण को दो कटोरों में बराबर बाँटें। हर कटोरे के ऊपर ताज़े ब्लूबेरी, थोड़ा सा कम वसा वाला ग्रेनोला, चिया बीज और एक चुटकी पिसी दालचीनी डालें।"]))
I.append(R(6324312,"चटपटा एवोकाडो टोस्ट","यह नाश्ता मलाईदार, खट्टे फल के रस से निखरा हुआ एक क्लासिक है, जो कुरकुरे और चिकने का एकदम सही संतुलन देता है।","1","1 स्लाइस",
["1 स्लाइस साबुत अनाज की ब्रेड","1/4 पका एवोकाडो","1 छोटा चम्मच नींबू का रस"],
["साबुत अनाज की ब्रेड को अपनी पसंद के सुनहरे भूरे कुरकुरेपन तक टोस्ट करें।","जब ब्रेड टोस्ट हो रही हो, तब 1/4 एवोकाडो का गूदा एक छोटे कटोरे में निकालें। नींबू का रस डालें और अपनी पसंद के अनुसार दरदरा या चिकना होने तक काँटे से मसलें।","मसले हुए मिश्रण को गरम टोस्ट पर बराबर फैलाएँ।","टोस्ट के कुरकुरे रहते ही तुरंत परोसें।"]))
I.append(R(6325149,"इंग्रिड हॉफ़मैन की सब्ज़ी भरी पोब्लानो मिर्च","पोब्लानो मिर्च का उपयोग ज़्यादातर मैक्सिकन व्यंजनों में होता है। ये स्वाद से भरपूर होती हैं और लगभग हर चीज़ भरने के लिए बहुत अच्छी हैं। इनमें हल्का सा तीखापन होता है, बस इतना कि स्वाद निखर जाए।","4","1 भरी हुई पोब्लानो",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","4 बड़ी पोब्लानो मिर्च","1 बड़ा चम्मच जैतून का तेल","8 औंस सफ़ेद (बटन) मशरूम (मोटे कटे हुए)","1 कप गाजर (कद्दूकस की हुई)","4 डंठल हरी प्याज़ (पतली कटी हुई)","4 कली लहसुन (बारीक कटा हुआ)","1/8 छोटा चम्मच नमक","2 बड़े चम्मच ताज़ी तुलसी (कटी हुई, या 2 छोटा चम्मच सूखी तुलसी की पत्तियाँ)","4 बड़े चम्मच केसो फ़्रेस्को (चूरा किया हुआ)"],
["ब्रॉयलर को पहले से गरम करें। ब्रॉयलर पैन पर फ़ॉइल बिछाएँ। फ़ॉइल पर हल्का सा नॉनस्टिक स्प्रे करें। पोब्लानो को पैन पर रखें और आँच से 4 इंच की दूरी पर, बीच-बीच में पलटते हुए, पोब्लानो के नरम होने और जगह-जगह हल्के जलने तक, लगभग 8 मिनट ब्रॉयल करें।","पोब्लानो को ज़िप-क्लोज़ प्लास्टिक बैग में रखें; हवा निकालकर बैग बंद करें। 15 मिनट रखा रहने दें। ब्रॉयलर चालू रखें।","एक बड़ी नॉनस्टिक कड़ाही में तेल को मध्यम-तेज़ आँच पर गरम करें। मशरूम, गाजर, हरी प्याज़, लहसुन और नमक डालें और बीच-बीच में चलाते हुए सब्ज़ियों के नरम होने तक, लगभग 8 मिनट पकाएँ। आँच से हटाएँ। तुलसी डालकर अच्छी तरह मिलने तक चलाएँ।","इस बीच, पोब्लानो का छिलका उतारें। एक चीरा लगाकर जेब बनाएँ और बीज निकाल दें। हर मिर्च में मशरूम के मिश्रण का एक-चौथाई भाग भरें और ऊपर 1 बड़ा चम्मच चीज़ डालें।","भरी हुई मिर्चों को आँच से 4 इंच की दूरी पर तब तक ब्रॉयल करें जब तक भरावन गरम न हो जाए और चीज़ पिघलना शुरू न हो, लगभग 4 मिनट।"]))
I.append(R(6325741,"शकरकंद और अदरक का सूप","इस अनोखे सूप में सिर्फ़ चार सामग्री हैं, इसलिए इसे बनाना बहुत आसान है।","6","1 कप",
["3 बड़े शकरकंद (छिले और छोटे टुकड़ों में कटे हुए)","3 कप फ़िल्टर किया हुआ पानी","2 औंस ताज़ी अदरक (कद्दूकस की और रस निकाला हुआ (लगभग 2 बड़े चम्मच))","1 छोटा चम्मच कोशर नमक"],
["एक मध्यम बर्तन में मध्यम आँच पर शकरकंद, पानी, अदरक का रस और नमक डालें। शकरकंद के नरम होने तक पकाएँ।","बैच में काम करते हुए, शकरकंद और पकाने का पानी ब्लेंडर या फ़ूड प्रोसेसर में डालें और चिकना होने तक पीस लें।"]))
I.append(R(6325867,"भुनी हुई सब्ज़ियाँ","लेखिका बारबरा सीलिग-ब्राउन कहती हैं, “सब्ज़ियाँ भूनने पर स्वादिष्ट लगती हैं। उनका स्वाद बढ़ जाता है और प्राकृतिक शर्करा कैरामलाइज़ हो जाती है, जिससे उनमें अच्छा कुरकुरापन आ जाता है। अपनी पसंद की कोई भी सब्ज़ी इस्तेमाल करके इस रेसिपी में बदलाव करें या एक बार में सिर्फ़ एक सब्ज़ी भूनें। मैं कभी-कभी छिले हुए चुकंदर या साफ़ की हुई ब्रसल्स स्प्राउट्स भूनती हूँ, और नापसंद करने वाले भी उन्हें हमेशा पसंद करते हैं!”","12","1/2 कप",
["छोटा बैंगन (बिना छिला, 1 इंच के टुकड़ों में कटा हुआ)","1/3 छोटा चम्मच समुद्री नमक","1 मध्यम तोरी (ज़ुकिनी) (1 इंच के टुकड़ों में कटी हुई)","1 मध्यम पीला स्क्वैश (1 इंच के टुकड़ों में कटा हुआ)","10 औंस क्रेमिनी (बेबी बेला) मशरूम","4 पूरे शैलट (छिले और चार भागों में कटे हुए)","1 मध्यम लाल शिमला मिर्च (1 इंच के टुकड़ों में कटी हुई)","1 मध्यम हरी शिमला मिर्च (1 इंच के टुकड़ों में कटी हुई)","1 मध्यम पीली शिमला मिर्च (1 इंच के टुकड़ों में कटी हुई)","1 कली लहसुन (अलग की और छिली हुई)","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/8 छोटा चम्मच काली मिर्च (ताज़ी पिसी हुई)","2 बड़े चम्मच बालसेमिक सिरका (अच्छी गुणवत्ता का)","1 टहनी जड़ी-बूटी की टहनियाँ (सजाने के लिए) (ताज़ी)"],
["ओवन को 425°F पर पहले से गरम करें।","बैंगन को एक बड़े कटोरे में रखें। बैंगन पर हल्का नमक छिड़कें और 10 मिनट रखा रहने दें। (इससे वह बहुत ज़्यादा तेल सोखने से बचेगा।) बाकी सब्ज़ियाँ डालें और जैतून के तेल के साथ मिलाएँ।","बेकिंग शीट पर बेकिंग पेपर बिछाएँ। सब्ज़ियों को बेकिंग शीट पर रखें। स्वादानुसार नमक और काली मिर्च छिड़कें। मनचाहे पकने तक, लगभग 20–30 मिनट भूनें। स्वादानुसार मसाले ठीक करें।","परोसने की थाली में रखें और ऊपर बालसेमिक सिरका छिड़कें। ताज़ी जड़ी-बूटियों से सजाएँ।"]))
I.append(R(6326662,"मशरूम और केल के साथ साबुत गेहूँ की पेने","यह मिट्टी जैसे स्वाद वाला साबुत गेहूँ की पेने का व्यंजन भुने हुए मशरूम, नरम केल और ऊपर से हल्के परमेसन के साथ एक आरामदायक लेकिन पौष्टिक भोजन के लिए भरपूर है। साबुत अनाज का पास्ता और पत्तेदार सब्ज़ियाँ फ़ाइबर और पोषक तत्व लाती हैं, जो पाचन को धीमा करने और रक्त ग्लूकोज़ (ब्लड शुगर) को स्थिर रखने में मदद करती हैं। यह एक संतुलित, पौधों पर आधारित विकल्प है जो मधुमेह के अनुकूल भोजन योजना में आसानी से फ़िट हो जाता है। यह DASH (उच्च रक्तचाप रोकने का आहार दृष्टिकोण) और भूमध्यसागरीय रेसिपी है।","4","2 औंस पास्ता और 1 कप सब्ज़ियाँ",
["8 औंस साबुत गेहूँ का रोटिनी पास्ता","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","12 औंस क्रेमिनी (बेबी बेला) मशरूम (कटे हुए)","3 कली लहसुन (बारीक कटा हुआ)","1/2 छोटा चम्मच पिसी लाल मिर्च के फ़्लेक्स","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","6 कप केल (कटा हुआ, डंठल हटाए हुए)","1/2 कप कम सोडियम वाला सब्ज़ी का शोरबा","1/4 कप परमेसन चीज़ (कद्दूकस किया हुआ)","1 बड़ा चम्मच नींबू का रस"],
["एक बड़े बर्तन में पानी उबालें। पास्ता डालें और पैकेट के निर्देशों के अनुसार अल डेंटे तक पकाएँ। छानने से पहले ½ कप पास्ता का पानी अलग रख लें।","जब पास्ता पक रहा हो, तब एक बड़ी कड़ाही में जैतून का तेल मध्यम आँच पर गरम करें। मशरूम डालें और बीच-बीच में चलाते हुए नरम और भूरे होने तक, लगभग 5-7 मिनट पकाएँ।","लहसुन, लाल मिर्च के फ़्लेक्स (अगर इस्तेमाल कर रहे हैं), नमक और काली मिर्च मिलाएँ। सुगंध आने तक 30 सेकंड पकाएँ।","केल और सब्ज़ी का शोरबा डालें, बीच-बीच में चलाते हुए पत्तों के नरम होने तक, लगभग 3-4 मिनट पकाएँ।","आँच धीमी करें और छना हुआ पास्ता कड़ाही में डालें। सब कुछ मिलाएँ, और नूडल्स पर बराबर लेप लगाने के लिए ज़रूरत हो तो थोड़ा सा अलग रखा पास्ता का पानी डालें।","आँच से हटाएँ, परमेसन चीज़ और नींबू का रस डालें और फिर से मिलाएँ।"]))
I.append(R(6326806,"सेब के चौकोर टुकड़े","सेब के चौकोर टुकड़े एक स्वादिष्ट मिठाई है जो साल के किसी भी समय के लिए एकदम सही है। बच्चों की पसंदीदा यह रेसिपी परिवार की पसंद है और मधुमेह वाले लोगों के लिए बढ़िया विकल्प है।","12","1 चौकोर टुकड़ा (61 ग्राम)",
["2 कप सेब (छिला, बीज निकाला, छोटे टुकड़ों में कटा हुआ)","1 बड़ा चम्मच नींबू का रस","1 कप सफ़ेद, साबुत गेहूँ का पेस्ट्री आटा","1 छोटा चम्मच बेकिंग पाउडर","1/2 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच नमक","1/4 कप मार्जरीन (बिना नमक की, पिघली हुई)","1/4 कप बिना चीनी की एप्पलसॉस","1/3 कप कम कैलोरी वाला चीनी का विकल्प","1/4 कप ब्राउन शुगर का विकल्प","1 बड़ा अंडा","1 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1/2 कप अखरोट (कटे हुए)"],
["अपने ओवन को 350 डिग्री F पर पहले से गरम करें। 8 x 8 इंच के बेकिंग पैन में बेकिंग पेपर बिछाएँ, आसानी से निकालने के लिए किनारों पर कागज़ बाहर लटकता रहने दें।","एक कटोरे में कटे सेबों को नींबू के रस के साथ मिलाएँ ताकि वे भूरे न पड़ें। एक तरफ़ रख दें।","एक मध्यम कटोरे में आटा, बेकिंग पाउडर, बेकिंग सोडा, पिसी दालचीनी और नमक को फेंटकर मिलाएँ।","एक बड़े मिक्सिंग कटोरे में मार्जरीन, एप्पलसॉस, दानेदार चीनी का विकल्प, ब्राउन शुगर का विकल्प, अंडा और वनीला एक्स्ट्रैक्ट को फेंटें।","मक्खन के मिश्रण को धीरे-धीरे आटे के मिश्रण में डालें, बस मिलने तक चलाएँ।","कटे हुए सेब और कटे अखरोट को धीरे से मिलाएँ।","घोल को तैयार बेकिंग पैन में बराबर फैलाएँ।","पहले से गरम किए ओवन में लगभग 30 से 40 मिनट या बीच में डाला गया टूथपिक साफ़ निकलने तक बेक करें।","पैन में 10 मिनट ठंडा होने दें, फिर बेकिंग पेपर के लटकते किनारों की मदद से उन्हें जाली पर उठाकर पूरी तरह ठंडा होने दें।","ठंडा होने पर 12 चौकोर टुकड़ों में काटें और परोसें।"]))
I.append(R(6327861,"केला अनानास “नाइस” क्रीम","केले को मुख्य सामग्री बनाकर तैयार की गई यह “नाइस” क्रीम रेसिपी आइसक्रीम का डेयरी-मुक्त और मधुमेह के अनुकूल विकल्प है। अतिरिक्त स्वाद के लिए इसके ऊपर कुछ और ताज़े फल या मेवे डालकर आज़माएँ।","6","1 कप (~127 ग्राम)",
["4 मध्यम केले (पके हुए, कटे हुए)","1 कप ताज़े अनानास के टुकड़े","1 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1/2 कप नारियल का दूध"],
["केले के स्लाइस और अनानास के टुकड़ों को बेकिंग पेपर लगी ट्रे पर एक परत में रखें। कम से कम 2 घंटे या ठोस होने तक फ़्रीज़ करें।","हाई-पावर ब्लेंडर या फ़ूड प्रोसेसर में जमे हुए केले के स्लाइस, जमे हुए अनानास के टुकड़े, वनीला एक्स्ट्रैक्ट और नारियल का दूध मिलाएँ।","सामग्री को चिकना और मलाईदार होने तक ब्लेंड करें, ज़रूरत के अनुसार किनारों से खुरचते रहें। अगर मिश्रण बहुत गाढ़ा है, तो ब्लेंड करने में मदद के लिए थोड़ा और नारियल का दूध डाल सकते हैं।","अगर आपको सॉफ़्ट-सर्व जैसी बनावट पसंद है, तो आप “नाइस” क्रीम का तुरंत आनंद ले सकते हैं। अगर आपको ज़्यादा ठोस बनावट पसंद है, तो मिश्रण को वायुरोधी डिब्बे में डालें और अतिरिक्त 1–2 घंटे फ़्रीज़ करें।"]))
I.append(R(6328863,"टमाटर और मीठे प्याज़ की स्टोवटॉप भिंडी","झटपट, आसान और आरामदायक - यह स्टोवटॉप भिंडी ऐसी लगती है जैसे घंटों पकी हो, लेकिन असल में यह 15 मिनट से भी कम में तैयार हो जाती है! हरी मिर्च वाले डिब्बाबंद टमाटर स्वाद और तीखापन देते हैं, लेकिन आप सामान्य डिब्बाबंद कटे टमाटर भी इस्तेमाल कर सकते हैं। जमी हुई भिंडी, कटी या साबुत, या ताज़ी भिंडी इस्तेमाल करें (ताज़ी भिंडी को पकने में ज़्यादा समय लगेगा)।","8","3/4 कप",
["1 बड़ा चम्मच एवोकाडो तेल या सूरजमुखी का तेल","1 बड़ा प्याज़ (विडालिया या कोई अन्य मीठा प्याज़)","2 कली लहसुन (बारीक कटा हुआ)","1 (16 औंस) पैकेट जमी हुई कटी या साबुत भिंडी (पिघलाई हुई)","2 (10 औंस) डिब्बे हरी मिर्च वाले कटे हुए टमाटर","3/4 छोटा चम्मच सूखा थाइम"],
["एक बड़े सॉसपैन में तेल को मध्यम-तेज़ आँच पर गरम करें। प्याज़ डालें और चलाते हुए हल्का सुनहरा होने तक, लगभग 5 मिनट पकाएँ। लहसुन डालें और चलाते हुए सुगंध आने तक, लगभग 1 मिनट पकाएँ।","पिघलाई हुई भिंडी, डिब्बाबंद टमाटर (रस सहित) और थाइम डालें, और बिना ढके तब तक पकाएँ जब तक तरल मनचाही गाढ़ाई तक न घट जाए, लगभग 5 मिनट, बीच-बीच में चलाते हुए। परोसें।"]))
I.append(R(6329487,"भुने पाइन नट्स के साथ लज़ीज़ एवोकाडो-स्ट्रॉबेरी सलाद","किसी खास अवसर के लायक, फिर भी बेहद सरल। यह मेरे अब तक के पसंदीदा व्यंजनों में से एक है। मौसम में स्ट्रॉबेरी की जगह पपीता या आम आज़माएँ।","4","रेसिपी का 1/4 भाग",
["1 मध्यम पका एवोकाडो (बेहतर हो हैस किस्म का, छिला, गुठली निकाला और टुकड़ों में कटा हुआ)","2 बड़े चम्मच 1 नींबू का रस","1 कप स्ट्रॉबेरी (डंठल हटाई और 1/2 इंच मोटे स्लाइस में कटी हुई)","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच रसभरी का सिरका","2 छोटा चम्मच शहद","1/8 छोटा चम्मच नमक (स्वादानुसार)","1/8 छोटा चम्मच ताज़ी पिसी काली मिर्च (स्वादानुसार)","2 कप रॉकेट (अरुगुला) (निवाले के आकार का)","2 बड़े चम्मच पाइन नट्स (भुने हुए)"],
["एवोकाडो को नींबू के रस के साथ एक बड़े, अप्रतिक्रियाशील कटोरे में मिलाएँ। बेरियाँ, तेल, सिरका, शहद, नमक और काली मिर्च डालें और अच्छी तरह मिलाएँ। चारों प्लेटों में से हर एक पर अरुगुला या वाटरक्रेस की परत के ऊपर परोसें। पाइन नट्स से सजाएँ।"]))
I.append(R(6330258,"भुनी हुई एप्पलसॉस","घर पर बनी भुनी हुई एप्पलसॉस एक स्वादिष्ट मिठाई या नाश्ता है। गरमाहट देने वाले मसालों के मिश्रण के साथ, यह निश्चित रूप से परिवार की पसंदीदा रेसिपी होगी।","4","1/2 कप",
["4 मध्यम सेब (छिले, बीज निकाले और कटे हुए)","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच शुगर-फ़्री बेकिंग चीनी का विकल्प","1 छोटा चम्मच पिसी दालचीनी","1/2 छोटा चम्मच पिसा जायफल","1/4 छोटा चम्मच पिसी लौंग","1 बड़ा चम्मच नींबू का रस","2/3 कप पानी"],
["ओवन को 375 डिग्री F पर गरम करें। शीट पैन पर बेकिंग पेपर बिछाएँ।","एक कटोरे में कटे हुए सेबों को जैतून का तेल, शुगर-फ़्री बेकिंग चीनी का विकल्प, पिसी दालचीनी, पिसा जायफल, पिसी लौंग और नींबू के रस के साथ तब तक मिलाएँ जब तक सेबों पर बराबर लेप न लग जाए।","मसाले लगे सेबों को शीट पैन पर एक परत में फैलाएँ।","सेबों को लगभग 30 मिनट या नरम और हल्का कैरामलाइज़ होने तक भूनें।","भुने हुए सेबों को ओवन से निकालें और कुछ मिनट ठंडा होने दें।","सेब और 2/3 कप पानी फ़ूड प्रोसेसर में डालें। मनचाही बनावट तक पल्स करें।","गरम या ठंडा परोसें।"]))
I.append(R(6331184,"चीज़ वाला शकरकंद और काली बीन्स कैसरोल","यह चीज़ वाला शकरकंद और काली बीन्स कैसरोल आज़माएँ, एक स्वादिष्ट और पेट भरने वाला व्यंजन जो शकरकंद की भरपूर मिठास, काली बीन्स के मिट्टी जैसे स्वाद और पिघले हुए चीज़ के चिपचिपे आराम को एक साथ लाता है। सबसे अच्छी बात? यह रेसिपी मधुमेह के अनुकूल है!","6","1 कप",
["2 बड़े शकरकंद (छिले और पतले कटे हुए)","15 औंस का डिब्बा काली बीन्स (छनी और धुली हुई)","1 कप मक्का (ताज़ा या जमा हुआ)","1/2 कप लाल प्याज़ (छोटे टुकड़ों में कटा हुआ)","1/4 कप ताज़ी धनिया पत्ती (कटी हुई, चाहें तो सजाने के लिए और)","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच लाल मिर्च पाउडर","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच काली मिर्च","2 बड़े चम्मच जैतून का तेल","1/2 कप चेडर चीज़ (कद्दूकस किया हुआ)"],
["ओवन को 375 डिग्री F पर पहले से गरम करें।","एक कटोरे में कटे हुए शकरकंद, काली बीन्स, मक्का, कटा हुआ लाल प्याज़ और कटी हुई धनिया पत्ती मिलाएँ।","एक छोटे कटोरे में पिसा जीरा, लाल मिर्च पाउडर, लहसुन पाउडर, कोशर नमक और काली मिर्च मिलाएँ।","शकरकंद के मिश्रण पर जैतून का तेल डालें और लपेटने के लिए मिलाएँ।","मसालों का मिश्रण शकरकंद के मिश्रण पर छिड़कें और बराबर लेप सुनिश्चित करने के लिए फिर से मिलाएँ।","शकरकंद के मिश्रण का आधा भाग तैयार बेकिंग डिश में डालें और एक बराबर परत बनाएँ।","शकरकंद की परत पर आधा कद्दूकस किया चेडर चीज़ छिड़कें।","बचे हुए शकरकंद के मिश्रण के साथ यही दोहराएँ और ऊपर बचा हुआ चीज़ डालें।","बेकिंग डिश को फ़ॉइल से ढकें और पहले से गरम किए ओवन में 30 मिनट बेक करें।","फ़ॉइल हटाएँ और अतिरिक्त 15 मिनट या शकरकंद के नरम होने और चीज़ के पिघलकर बुलबुले उठने तक बेक करें।","परोसने से पहले कैसरोल को 10 मिनट आराम करने दें। चाहें तो ताज़ी धनिया पत्ती से सजाएँ।"]))
